(7151269, 1096779, 26464, '<td valign="top">i love the light!</td>', 'i love the light!', '2014-01-03 12:25:59.000000', NULL, 1),
(7151270, 1096733, 26464, '<td valign="top">lots of life in death valley :-)</td>', 'lots of life in death valley :-)', '2014-01-03 12:26:39.000000', NULL, 1),
(7151273, 1096716, 26464, '<td valign="top">great portrait. 8</td>', 'great portrait. 8', '2014-01-03 12:30:44.000000', NULL, 1),
(7151290, 1096666, 173844, '<td valign="top">All too common, but still powerfully sad, scene.  I don''t know where this is, but in America there''s a great gulf between our wealth and our determination that all people should share in it.  Well composed, good contrast, good use of angled perspective and partial silhouetting.</td>', 'All too common, but still powerfully sad, scene.  I don''t know where this is, but in America there''s a great gulf between our wealth and our determination that all people should share in it.  Well composed, good contrast, good use of angled perspective and partial silhouetting.', '2014-01-03 13:00:27.000000', NULL, 1),
(7151291, 1096603, 173844, '<td valign="top">A pretty spot well photographed.</td>', 'A pretty spot well photographed.', '2014-01-03 13:02:54.000000', NULL, 1),
(7151292, 1095873, 173844, '<td valign="top">This looks terrific!  More like a bird than a dolphin, though.</td>', 'This looks terrific!  More like a bird than a dolphin, though.', '2014-01-03 13:04:50.000000', NULL, 1),
(7151296, 1096332, 173844, '<td valign="top">So interesting that the posts on the left appear to be holding up the mountain.  It throws perceptions and expectations out of whack. Entering Magritte territory.  The dark edges of the posts seem to be shadows thrown on a flat, vertical, paper lake background.</td>', 'So interesting that the posts on the left appear to be holding up the mountain.  It throws perceptions and expectations out of whack. Entering Magritte territory.  The dark edges of the posts seem to be shadows thrown on a flat, vertical, paper lake background.', '2014-01-03 13:12:44.000000', NULL, 1),
(7151298, 1096508, 173844, '<td valign="top">Nice close-up of this fascinating detail.  Reminds me of a frosty mug of root beer.</td>', 'Nice close-up of this fascinating detail.  Reminds me of a frosty mug of root beer.', '2014-01-03 13:15:59.000000', NULL, 1),
(7151300, 1096806, 173844, '<td valign="top">Wow, this is beautiful.  Perfect amount of sky.</td>', 'Wow, this is beautiful.  Perfect amount of sky.', '2014-01-03 13:18:03.000000', NULL, 1),
