(7152852, 1096154, 65234, '<td valign="top">Perfect timing!  Love that you got eye contact, too.</td>', 'Perfect timing!  Love that you got eye contact, too.', '2014-01-06 09:56:23.000000', NULL, 1),
(7152855, 1096832, 65234, '<td valign="top">Maybe a tad oversaturated and the water is a bit cyan, but I''m going to overlook that because the scene is so very magical.</td>', 'Maybe a tad oversaturated and the water is a bit cyan, but I''m going to overlook that because the scene is so very magical.', '2014-01-06 09:57:51.000000', NULL, 1),
(7152862, 1096609, 65234, '<td valign="top">Great capture!  The DOF is great with just that bit of motion in the wings.  Not sure why you desaturated the jay, but maybe if you left everything fully saturated the background was too distracting, but you weren''t happy with B&amp;W, either.  I just kinda'' miss the beautiful color I associate with these birds.</td>', 'Great capture!  The DOF is great with just that bit of motion in the wings.  Not sure why you desaturated the jay, but maybe if you left everything fully saturated the background was too distracting, but you weren''t happy with B&W, either.  I just kinda'' miss the beautiful color I associate with these birds.', '2014-01-06 10:00:55.000000', NULL, 1),
(7152863, 1096515, 65234, '<td valign="top">LOVE the distorted reflections.  Terrific image.</td>', 'LOVE the distorted reflections.  Terrific image.', '2014-01-06 10:01:20.000000', NULL, 1),
(7152865, 1096567, 65234, '<td valign="top">Lovely, and the sun''s last rays are perfectly captured.</td>', 'Lovely, and the sun''s last rays are perfectly captured.', '2014-01-06 10:01:48.000000', NULL, 1),
(7152871, 1096538, 65234, '<td valign="top">Oh, I love this!    So cute with all that eye contact, and one over there on the left completely oblivious to you, and one at the top being contemplative. Must have been fun to see in person; thanks for sharing.</td>', 'Oh, I love this!    So cute with all that eye contact, and one over there on the left completely oblivious to you, and one at the top being contemplative. Must have been fun to see in person; thanks for sharing.', '2014-01-06 10:03:41.000000', NULL, 1),
